@Interceptor
@Timed
public class TimingInterceptor {
    @AroundInvoke
    Object measure(InvocationContext ctx) throws Exception {
        long t0 = System.nanoTime();
        try { return ctx.proceed(); }                 // downstream chain
        finally { metrics.record(ctx.getMethod().getName(), System.nanoTime() - t0); }
    }
}

